import re,time
t=str(int(time.time()))
for fn in ['index.html','chat.html','system.html']:
    s=open(fn,encoding='utf-8').read()
    if 'nox-hud-s1.js' not in s:
        open(fn+'.bak_s1_hud','w',encoding='utf-8').write(s)
        s=s.replace('</body>','<script type="module" src="./nox-hud-s1.js?v='+t+'"></script>\n</body>',1)
    open(fn,'w',encoding='utf-8').write(s)
for fn in ['chat.html','atlas.html','voice.html','index.html']:
    s=open(fn,encoding='utf-8').read()
    for f in ['nox-chat-living.css','nox-chat-living.js','nox-atlas-s1.js','nox-sl-s1.css']:
        s=re.sub(f.replace('.','\\.')+r'\?v=[0-9]*',f+'?v='+t,s)
    open(fn,'w',encoding='utf-8').write(s)
open('qa/rework/chat.fixed','a',encoding='utf-8').write('\nS1: быстрые команды — sl-tag /память /коротко /подробно /учить над полем ввода; HUD-рамки Arwes (vendor/nox-fx/hud.js) на chat.\n')
open('qa/rework/index.fixed','a',encoding='utf-8').write('\nS1: HUD-рамки Arwes createFrame (vendor/nox-fx/hud.js) на карточках и плитках; главная по эталону не менялась (решение владельца отложено).\n')
open('qa/rework/voice.fixed','a',encoding='utf-8').write('\nS1: нативные select скрыты принудительно (остаются только sl-select).\n')
open('qa/rework/atlas.fixed','a',encoding='utf-8').write('\nS1: глобус грузится лениво после события load (+200 мс), до этого skeleton.\n')
print('w12 ok')
P
